# Resort-scoped demo reset: wipes resort 1 transactional data only,
# leaves other tenants/resorts (e.g. the resort-2 sheet import) untouched.
& "C:\wamp64\bin\mysql\mysql9.1.0\bin\mysql.exe" -uroot --port=3306 resorthub -e "SET FOREIGN_KEY_CHECKS=0; DELETE FROM booking_nights WHERE itemId IN (SELECT id FROM booking_items WHERE bookingId IN (SELECT id FROM bookings WHERE resortId=1)); DELETE FROM booking_items WHERE bookingId IN (SELECT id FROM bookings WHERE resortId=1); DELETE FROM payments WHERE bookingId IN (SELECT id FROM bookings WHERE resortId=1); DELETE FROM payment_intents WHERE resortId=1; DELETE FROM bookings WHERE resortId=1; DELETE FROM guests WHERE resortId=1; DELETE FROM activity_slots WHERE catalogId IN (SELECT id FROM activity_catalog WHERE resortId=1); DELETE FROM activity_schedules WHERE catalogId IN (SELECT id FROM activity_catalog WHERE resortId=1); DELETE FROM activity_catalog WHERE resortId=1; DELETE FROM fb_bill_items WHERE billId IN (SELECT id FROM fb_bills WHERE resortId=1); DELETE FROM fb_bills WHERE resortId=1; DELETE FROM expenses WHERE resortId=1; DELETE FROM counters WHERE resortId=1; SET FOREIGN_KEY_CHECKS=1;"
Write-Host "resort 1 transactional data reset"
